export async function retrieveContext(query: string): Promise<Document[]> {
  // 1. Naive sequential embedding
  const embedding = await embedder.encode(query);

  // 2. High-latency brute-force vector search
  const rawMatches = await vectorStore.query({
    vector: embedding,
    topK: 50,
    includeMetadata: true
  });

  // 3. Blocking re-ranker passes sequentially
  const filtered = await crossEncoder.rerank(query, rawMatches);
  return filtered.slice(0, 10);
}

